insert into public.articles (title, slug, excerpt, content, cover_image_url, author, status, published_at) values
('Panduan Lengkap Isi Token Listrik PLN', 'panduan-isi-token-listrik', 'Langkah demi langkah mengisi token listrik prabayar lewat Hesolvian, dari input ID meter sampai token masuk.', '', null, 'Admin', 'published', '2026-09-20T09:00:00.000Z'),
('Cara Melacak Status Transaksi PPOB', 'cara-melacak-status-transaksi', 'Kenali empat tahap audit transaksi: diterima, diproses, dibayar, selesai.', '', null, 'Admin', 'published', '2026-09-20T09:00:00.000Z'),
('Tips Aman Bertransaksi di Loket Digital', 'tips-aman-bertransaksi', 'Ciri-ciri mitra resmi, pengecekan hash server, dan kebiasaan yang bikin transaksi aman.', '', null, 'Admin', 'published', '2026-09-20T09:00:00.000Z'),
