insert into public.faqs (category, question, answer, is_published, sort_order) values
('pembayaran', 'Berapa lama transaksi diproses setelah pembayaran berhasil?', 'Sebagian besar transaksi diproses secara instan dalam 5 hingga 30 detik setelah pembayaran terverifikasi. Untuk beberapa layanan atau saat server operator mengalami antrean, proses dapat memerlukan waktu 1-5 menit.', true, 0),
('pulsa', 'Pulsa atau paket data belum masuk, apa yang harus dilakukan?', 'Pastikan nomor tujuan sudah benar dan masa aktif kartu masih berlaku. Coba tunggu 1-3 menit, lalu cek kembali saldo pulsa atau kuota Anda. Jika belum masuk, periksa status transaksi di halaman Lacak Transaksi atau hubungi Customer Care kami dengan melampirkan nomor transaksi.', true, 1),
('token', 'Token listrik PLN belum diterima setelah pembayaran, bagaimana?', 'Nomor token PLN 20 digit otomatis tampil di rincian transaksi setelah pembayaran berhasil. Jika halaman sempat tertutup, Anda dapat melihatnya kembali di menu Lacak Transaksi atau mengunduh struk resmi. Jika status masih diproses, tunggu 1-2 menit atau sampaikan melalui formulir pengaduan.', true, 2),
('pembayaran', 'Saldo sudah terpotong, tetapi transaksi masih diproses. Apa yang harus dilakukan?', 'Hal ini terjadi ketika pembayaran Anda telah berhasil diverifikasi oleh bank, namun sistem sedang menunggu konfirmasi akhir dari penyedia layanan (PLN/Operator). Anda dapat menekan tombol "Cek Status Sekarang" pada halaman transaksi atau menunggu beberapa menit agar sistem menyelesaikan sinkronisasi secara otomatis.', true, 3),
('refund', 'Bagaimana jika transaksi gagal tetapi saldo sudah terpotong?', 'Jangan khawatir, saldo dan dana Anda dijamin aman. Jika transaksi dinyatakan gagal oleh sistem atau nomor tujuan tidak valid, dana pembayaran akan dikembalikan secara penuh (100% refund) sesuai metode pembayaran yang digunakan tanpa potongan biaya admin.', true, 4),
('riwayat', 'Bagaimana cara melihat kembali riwayat transaksi?', 'Buka menu "Lacak Transaksi" pada navigasi. Masukkan Nomor Transaksi atau nomor HP/ID Pelanggan Anda untuk melihat kembali rincian pembayaran, nomor token PLN, serta mencetak atau mengunduh struk bukti transaksi sah.', true, 5)
